  BASE_TAGS_COLOR: "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0446\u0432\u0435\u0442 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u043A \u0442\u044D\u0433\u0430\u043C \u0432 \u0431\u0430\u0437\u0435 \u0434\u0430\u043D\u043D\u044B\u0445",
  BASE_TAGS_COLOR_DESC: "\u042D\u0442\u0430 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0434\u0435\u043B\u0430\u0435\u0442 \u0442\u044D\u0433\u0438 \u0432 \u0431\u0430\u0437\u0435 \u0434\u0430\u043D\u043D\u044B\u0445 \u043F\u043E\u0445\u043E\u0436\u0438\u043C\u0438 \u043D\u0430 \u0442\u044D\u0433\u0438 \u0432 \u0444\u0430\u0439\u043B\u0430\u0445, \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044F \u0446\u0432\u0435\u0442 \u0438 \u043E\u0442\u0441\u0442\u0443\u043F\u044B. \u0412\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u0435, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u0442\u044D\u0433\u0438 \u043E\u0442\u043E\u0431\u0440\u0430\u0436\u0430\u043B\u0438\u0441\u044C \u0442\u0430\u043A \u0436\u0435, \u043A\u0430\u043A \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u0432\u043E\u0439\u0441\u0442\u0432\u0430.",
  STYLE_FORMULA_TAGS: "\u0421\u0442\u0438\u043B\u0438\u0437\u043E\u0432\u0430\u0442\u044C \u0441\u0432\u043E\u0439\u0441\u0442\u0432\u0430 \u0438\u0437 \u043A\u043E\u043B\u043E\u043D\u043A\u0438 formula.tags \u043A\u0430\u043A \u0442\u044D\u0433\u0438",
  STYLE_FORMULA_TAGS_DESC: '\u0414\u0435\u043B\u0430\u0435\u0442 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0441\u043F\u0438\u0441\u043A\u0430, \u0441\u0433\u0435\u043D\u0435\u0440\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0444\u043E\u0440\u043C\u0443\u043B\u043E\u0439 \u043F\u043E\u0434 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435\u043C "tags" \u043F\u043E\u0445\u043E\u0436\u0438\u043C\u0438 \u043D\u0430 \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u044B\u0435 \u0442\u044D\u0433\u0438. \u042D\u0442\u043E \u0432\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0446\u0432\u0435\u0442 \u0442\u044D\u0433\u043E\u0432 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u0446\u0432\u0435\u0442\u0430.',
