// src/utils/propertyNameSuggester.ts
var import_obsidian26 = require("obsidian");
var PropertyNameSuggest = class extends import_obsidian26.AbstractInputSuggest {
  constructor(app, inputEl, allowedTypes) {
    super(app, inputEl);
    if (allowedTypes)
      this.allowedTypes = new Set(allowedTypes);
  }
  getSuggestions(query) {
    const querySanitized = query.trim().toLowerCase();
    const allAllowedPropertyNames = this.getAllPropertyNamesRestricted(this.allowedTypes);
    if (!querySanitized)
      return allAllowedPropertyNames;
    return allAllowedPropertyNames.filter((p) => p.toLowerCase().includes(querySanitized));
  }
  renderSuggestion(value, el) {
    el.setText(value);
  }
  getAllPropertyNamesRestricted(allowedTypes) {
    let properties = this.app.metadataTypeManager.getAllProperties();
    const names = Object.values(properties).filter((p) => !allowedTypes || allowedTypes.has(p == null ? void 0 : p.widget)).map((p) => p == null ? void 0 : p.name).filter((n) => typeof n === "string" && n.length > 0);
    return Array.from(new Set(names)).sort((a, b) => a.localeCompare(b));
  }
};

// src/utils/settingsHelper.ts
function enhanceFormatTextArea(plugin, text, initialValue, onValidChange) {
  text.setValue(initialValue);
  text.setPlaceholder(i18n.t("PROPERTY_FORMAT_PLACEHOLDER"));
  const textareaEl = text.inputEl;
  const parent = textareaEl.parentElement;
  if (!parent) return;
  const wrapper = createDiv();
  wrapper.addClass("pp-format-wrapper");
  parent.insertBefore(wrapper, textareaEl);
  wrapper.appendChild(textareaEl);
  const errorEl = createDiv();
  errorEl.addClass("pp-format-error");
  wrapper.appendChild(errorEl);
  const applyValidationState = (tpl) => {
    const err = validateFormatTemplate(tpl);
    if (err) {
      textareaEl.addClass("pp-format-invalid");
      errorEl.textContent = err;
    } else {
      textareaEl.removeClass("pp-format-invalid");
      errorEl.textContent = "";
    }
  };
  applyValidationState(initialValue);
  text.onChange(async (value) => {
    await onValidChange(value);
    applyValidationState(value);
    updateLongTexts(document.body, plugin);
  });
}

// src/modals/settingItemModals.ts
var import_obsidian27 = require("obsidian");
var AddPropertyModal = class extends import_obsidian27.Modal {
  constructor(allowedTypes, plugin, modalCallback) {
    super(plugin.app);
    this.plugin = plugin;
    this.allowedTypes = allowedTypes;
    this.modalCallback = modalCallback;
    this.result = "";
  }
  onOpen() {
    const { contentEl } = this;
    new import_obsidian27.Setting(contentEl).setName(i18n.t("ADD_PROPERTY")).addSearch((search) => {
      search.setValue("");
      search.setPlaceholder(i18n.t("PROPERTY_SEARCH_PLACEHOLDER"));
      const suggester = new PropertyNameSuggest(this.plugin.app, search.inputEl, this.allowedTypes);
      suggester.onSelect(async (value) => {
        suggester.setValue(value);
        suggester.close();
        this.result = value;
        void this.modalCallback(this.result);
        this.close();
      });
    });
    new import_obsidian27.Setting(contentEl).addButton(
      (btn) => btn.setButtonText(i18n.t("SAVE")).setCta().onClick(async () => {
        void this.modalCallback(this.result);
        this.close();
      })
    ).addButton(
      (btn) => btn.setButtonText(i18n.t("CANCEL")).onClick(() => {
        this.close();
      })
    );
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};
