var SvgSuggestModal = class extends import_obsidian37.SuggestModal {
  constructor(app, plugin) {
    super(app);
    this.propName = plugin.settings.iconProperty;
    this.iconIds = (0, import_obsidian37.getIconIds)();
  }
  getSuggestions(query) {
    return this.iconIds.filter((val) => {
      return val.toLowerCase().includes(query.toLowerCase());
    });
  }
  renderSuggestion(id, el) {
    let svg = (0, import_obsidian37.getIcon)(id) || "";
    el.append(svg);
    el.classList.add("image-suggestion-item");
    el.classList.add("svg-icon");
  }
  onChooseSuggestion(id) {
    if (id) {
      let file = this.app.workspace.getActiveFile();
      if (file instanceof import_obsidian37.TFile) {
        void this.app.fileManager.processFrontMatter(file, (fm) => {
          setNestedProperty(fm, this.propName, id);
        });
      }
    }
  }
};

